package com.jeandev.lovemeter.platform

import androidx.compose.runtime.Composable
import androidx.compose.runtime.DisposableEffect
import androidx.compose.ui.Modifier
import cafe.adriel.voyager.navigator.LocalNavigator
import com.jeandev.lovemeter.ui.screens.IntroNombreScreen
import kotlinx.browser.document
import org.w3c.dom.HTMLSourceElement
import org.w3c.dom.HTMLVideoElement
import org.w3c.dom.Node

@Composable
actual fun VideoPlayer(resourceName: String, modifier: Modifier) {
    val navigator = LocalNavigator.current

    DisposableEffect(resourceName) {
        // 1. Forzar el fondo negro en el BODY y en el elemento HTML
        val htmlElement = document.documentElement
        val bodyElement = document.body

        val originalBodyBg = bodyElement?.style?.backgroundColor ?: ""

        // Aplicamos negro absoluto a los contenedores raíz
        bodyElement?.style?.backgroundColor = "black"

        val videoElement = document.createElement("video") as HTMLVideoElement
        val sourceElement = document.createElement("source") as HTMLSourceElement

        sourceElement.src = "raw/$resourceName.mp4"
        sourceElement.type = "video/mp4"

        videoElement.apply {
            autoplay = true
            controls = false
            muted = false
            appendChild(sourceElement)

            style.apply {
                position = "fixed"
                top = "0px"
                left = "50%"
                height = "100vh"
                width = "auto"
                transform = "translateX(-50%)"
                objectFit = "cover"
                zIndex = "2147483647" // Máximo valor posible
                backgroundColor = "black"
            }

            onended = {
                // Restaurar colores originales
                bodyElement?.style?.backgroundColor = originalBodyBg

                // Salir de pantalla completa
                val doc = document.asDynamic()
                if (document.fullscreenElement != null) {
                    doc.exitFullscreen()
                }

                navigator?.popAll()
                navigator?.push(IntroNombreScreen())
                Unit
            }
        }

        val targetNode: Node = document.body?.asDynamic().shadowRoot.unsafeCast<Node?>()
            ?: document.body!!

        targetNode.appendChild(videoElement)

        onDispose {
            videoElement.pause()
            videoElement.remove()
            bodyElement?.style?.backgroundColor = originalBodyBg
        }
    }
}

actual fun enterFullscreen() {
    val docEl = document.documentElement.asDynamic()

    // Solicitamos pantalla completa con soporte para varios navegadores
    if (docEl.requestFullscreen != undefined) {
        docEl.requestFullscreen()
    } else if (docEl.webkitRequestFullscreen != undefined) { // Safari/Chrome antiguos
        docEl.webkitRequestFullscreen()
    } else if (docEl.msRequestFullscreen != undefined) { // IE/Edge antiguos
        docEl.msRequestFullscreen()
    }
}