package com.jeandev.lovemeter.platform

import kotlinx.browser.window
import kotlinx.coroutines.await

class JsPlatform : Platform {

    override val name: String = buildString {
        appendLine("🌐 Plataforma Web")
        appendLine("Navegador: ${getBrowserName()}")
        appendLine("Plataforma: ${window.navigator.platform}")
        appendLine("User Agent: ${window.navigator.userAgent}")
        appendLine("Idioma: ${window.navigator.language}")
        appendLine("Idiomas: ${window.navigator.languages?.joinToString()}")
        appendLine("Online: ${window.navigator.onLine}")
        appendLine("Cookies: ${window.navigator.cookieEnabled}")
    }

    override suspend fun getPublicIp(): String {
        return try {
            val response = window
                .fetch("https://api.ipify.org?format=json")
                .await()

            val json = response.json().await().unsafeCast<dynamic>()
            json.ip as String
        } catch (e: dynamic) {
            "No disponible"
        }
    }
}

actual fun getPlatform(): Platform = JsPlatform()

private fun getBrowserName(): String {
    val ua = window.navigator.userAgent
    return when {
        ua.contains("Firefox") -> "Firefox"
        ua.contains("Edg") -> "Edge"
        ua.contains("Chrome") -> "Chrome"
        ua.contains("Safari") -> "Safari"
        else -> "Desconocido"
    }
}
