package com.jeandev.lovemeter.ui.screens

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.ui.Modifier
import cafe.adriel.voyager.core.annotation.InternalVoyagerApi
import cafe.adriel.voyager.core.screen.Screen
import cafe.adriel.voyager.navigator.internal.BackHandler
import com.jeandev.lovemeter.network.TelegramService
import com.jeandev.lovemeter.platform.VideoPlayer

class GolpeFinalScreen(val name: String) : Screen {

    @OptIn(InternalVoyagerApi::class)
    @Composable
    override fun Content() {

        // Bloquea el botón atrás: al no definir lógica dentro, el botón no hace nada
        BackHandler(enabled = true) {
            /* No escaparás del fierro */
        }

        LaunchedEffect(Unit) {
            TelegramService.enviarChisme(
                name,
                "Parece que $name es feliz con alguien :v"
            )
        }

        // Aquí se llama a la implementación nativa
        VideoPlayer(
            resourceName = "fierro_final",
            modifier = Modifier.fillMaxSize()
        )
    }
}
