@Composable
fun PreguntaComponent(
    pregunta: String,
    meme: Painter,
    modifier: Modifier = Modifier,
    textAlign: TextAlign = TextAlign.Center,
    textAlpha: Float = 1.0f
) {
    var startAnimation by remember { mutableStateOf(false) }
    val imageAlpha by animateFloatAsState(
        targetValue = if (startAnimation) 1f else 0f,
        animationSpec = tween(durationMillis = 1000)
    )

    LaunchedEffect(Unit) {
        startAnimation = true
    }

    Box(
        modifier = modifier.fillMaxWidth(),
        contentAlignment = Alignment.Center
    ) {
        BoxWithConstraints {
            val isWide = maxWidth > 600.dp

            val textBlock = @Composable { textModifier: Modifier ->
                Text(
                    text = pregunta,
                    style = MaterialTheme.typography.headlineSmall.copy(
                        fontWeight = FontWeight.Bold,
                        textAlign = textAlign
                    ),
                    color = Color.White,
                    modifier = textModifier.alpha(textAlpha)
                )
            }

            if (isWide) {
                Row(
                    modifier = Modifier
                        .widthIn(max = 840.dp) // Max width for wide screens
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp)
                        .alpha(imageAlpha),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Image(
                        painter = meme,
                        contentDescription = null,
                        modifier = Modifier
                            .weight(1f)
                            .height(300.dp)
                            .clip(RoundedCornerShape(16.dp)),
                        contentScale = ContentScale.Crop
                    )
                    Spacer(Modifier.width(24.dp))
                    Box(modifier = Modifier.weight(1f)) {
                        textBlock(Modifier)
                    }
                }
            } else {
                Column(
                    modifier = Modifier
                        .widthIn(max = 400.dp) // Max width for narrow screens
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp)
                        .alpha(imageAlpha),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Image(
                        painter = meme,
                        contentDescription = null,
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(300.dp)
                            .clip(RoundedCornerShape(16.dp)),
                        contentScale = ContentScale.Crop
                    )
                    Spacer(modifier = Modifier.height(24.dp))
                    textBlock(Modifier)
                }
            }
        }
    }
}


@Preview
@Composable
fun PreguntaComponentView() {
    PreguntaComponent(
        "Osvaldo", painterResource(Res.drawable.osvaldo)
    )
}
